  v_svg:=$d$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 850 270" width="850" height="270" role="img"><rect width="850" height="270" fill="white"/><style>.h{font-family:Arial,Helvetica,sans-serif;font-size:18px;font-weight:700;fill:#111}.t{font-family:Arial,Helvetica,sans-serif;font-size:17px;fill:#111}.m{font-family:"Courier New",Courier,monospace;font-size:17px;fill:#111}.g{fill:white;stroke:#333;stroke-width:1.2}</style><rect class="g" x="0" y="0" width="690" height="50"/><text class="h" x="345" y="31" text-anchor="middle"></text><rect class="g" x="690" y="0" width="160" height="50"/><text class="h" x="770" y="31" text-anchor="middle">Answer</text><rect class="g" x="0" y="50" width="690" height="55"/><text class="t" x="10" y="77.5">The number of transitions that result in a different state</text><rect class="g" x="690" y="50" width="160" height="55"/><text class="t" x="700" y="77.5">3</text><rect class="g" x="0" y="105" width="690" height="55"/><text class="t" x="10" y="132.5">The number of transitions with associated outputs</text><rect class="g" x="690" y="105" width="160" height="55"/><text class="t" x="700" y="132.5">2</text><rect class="g" x="0" y="160" width="690" height="55"/><text class="t" x="10" y="187.5">The label that should replace ‘X’</text><rect class="g" x="690" y="160" width="160" height="55"/><text class="t" x="700" y="187.5">Start</text><rect class="g" x="0" y="215" width="690" height="55"/><text class="t" x="10" y="242.5">The final or halting state</text><rect class="g" x="690" y="215" width="160" height="55"/><text class="t" x="700" y="242.5">S3</text></svg>$d$; v_hash:=encode(digest(v_svg,'sha256'),'hex');
