<rect class="g" x="330" y="140" width="112" height="40"/><line class="g" x1="405" y1="140" x2="405" y2="180"/><text class="t" x="367" y="166" text-anchor="middle">Cat</text>
<rect class="g" x="535" y="140" width="112" height="40"/><line class="g" x1="610" y1="140" x2="610" y2="180"/><text class="t" x="572" y="166" text-anchor="middle">Fish</text><text class="t" x="628" y="166" text-anchor="middle">0</text>
