</svg>$e$; v_hash:=encode(digest(v_svg,'sha256'),'hex');
  IF NOT EXISTS (SELECT 1 FROM mark_schemes WHERE id='e6e1cb4c-e8a9-4d6f-9a13-947daae77831'::uuid AND source_paper_id=v_source AND status='approved')
